  ({ color, width, ...(o.cap ? { cap: o.cap } : {}), ...(o.join ? { join: o.join } : {}), ...(o.dash ? { dashArray: o.dash } : {}), ...(o.offset ? { dashOffset: o.offset } : {}) }) as { color: string; width: number };

